 function pinRule(ref:RuleReference){updateSession(s=>({...s,ruleReferences:[...(s.ruleReferences||[]).filter(r=>r.id!==ref.id),ref].slice(-6)}))}
 function saveOutcome(value:OutcomeEdit){update(c=>({...c,events:editingEvent?c.events.map(e=>e.id===editingEvent?{...e,...value}:e):[...c.events,{...value,id:uid(),date:new Date().toISOString()}]}));setModal('');setNotice(editingEvent?'Campaign history updated.':'Recorded. Future sessions will use this outcome.');}
 function exportData(){const blob=new Blob([JSON.stringify({version:2,campaigns,active,sessionId},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='waypoint-campaigns.json';a.click();URL.revokeObjectURL(url);setNotice('Campaign backup downloaded.')}
 // Backups and restore points are added as copies, so existing campaigns are never replaced.
 function addCopies(data:{campaigns?:unknown}|null,label:string){const list=data?.campaigns;if(!Array.isArray(list)||!list.length||!list.every(validateCampaign))throw new Error('This is not a valid Waypoint backup.');const restored:Campaign[]=list.map((c:Campaign)=>({...c,id:uid(),name:c.name+' ('+label+')'}));setCampaigns(cs=>[...cs,...restored]);setActive(restored[0].id);setSessionId(restored[0].sessions[0]?.id||'');setReady(true);return restored.length}
 async function importData(file?:File){if(!file)return;try{if(file.size>50000000)throw new Error('Please use a backup smaller than 50 MB.');addCopies(JSON.parse(await file.text()),'imported');setNotice('Backup imported as separate campaigns.')}catch(e){setError(e instanceof Error?e.message:'Import failed.')}finally{if(fileRef.current)fileRef.current.value=''}}
 function coachPrompt(prompt:string){promptDraft.replace(prompt.slice(0,10000),'DM response');setNotice('Add what the players said, then generate your response.');requestAnimationFrame(()=>{const el=document.getElementById('quick-prompt');el?.scrollIntoView({block:'center',behavior:'smooth'});el?.focus()})}
