 const nav:[View,typeof BookOpen][]=[['Session desk',BookOpen],['Foresight',Telescope],['Next session',Compass],['Saved material',Sparkles],['Rules library',BookOpen],['Campaign hub',Compass],['Campaign',Map],['World wiki',BookOpen],['Party & preferences',Users],['Session journal',FileText],['Chronicle',ScrollText],['Player handouts',FileText]];
